bg=4
patterns={1:[[1,0,1],[1,1,1],[1,1,0]],7:[[1,0,1],[0,1,1],[1,0,1]],9:[[1,1,0],[1,0,0],[1,1,1]]}
out=[[bg]*19 for _ in range(7)]
for start,col in zip([1,7,13],[1,7,9]):
    for r in range(1,6):
        for c in range(start,start+5): out[r][c]=col
    for i in range(3):
        for j in range(3): out[2+i][start+1+j]=bg if patterns[col][i][j] else col
print('\n'.join(' '.join(map(str,row)) for row in out))

patterns[9]=[[0,1,1],[0,1,0],[1,1,1]]
out=[[4]*19 for _ in range(7)]
for start,col in zip([1,7,13],[1,7,9]):
    for r in range(1,6):
        for c in range(start,start+5): out[r][c]=col
    for i in range(3):
        for j in range(3): out[2+i][start+1+j]=4 if patterns[col][i][j] else col
print(out)
